// 1. Extrai a mensagem e o histórico de conversa recebidos do site
const item = $input.first().json;
let body = item.body || item;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch(e) { body = {}; }
}

const userMessage = body.message || 'Olá';
const conversationHistory = Array.isArray(body.history) ? body.history : [];

// 2. System Prompt especialista com todas as regras da Valoriza Car
const systemInstruction = `Você é a "Valéria", a consultora virtual especialista em Proteção Veicular da Valoriza Car (site oficial: valorizacar.com.br).
Seu objetivo é conversar de forma amigável, humanizada, consultiva e empática com o visitante para entender suas necessidades e recomendar o plano de proteção veicular ideal sob medida.

REGRAS E TABELA OFICIAL DE PREÇOS DA VALORIZA CAR:
1. PLANO ESSENCIAL BASE (OBRIGATÓRIO E FIXO):
   - Custo: R$ 119,90/mês (apenas R$ 4,00 por dia).
   - Já inclui 100%:
     • Roubo e Furto (até 100% Tabela FIPE);
     • Colisão e Perda Total (oficinas referenciadas ou indenização PT);
     • Danos da Natureza (alagamentos, enchentes, granizo, queda de árvores);
     • Assistência 24h básica (Guincho 100 km, chaveiro, troca de pneus, socorro de bateria);
     • Clube de Descontos gratuito (Academias Pratique, farmácias, Cinemark, Domino's, etc.).

2. FAIXAS DE VALOR DO VEÍCULO (TABELA FIPE):
   - Até R$ 30 mil: +R$ 0,00 (Base R$ 119,90)
   - Até R$ 50 mil: +R$ 0,00 (Padrão: Base R$ 119,90)
   - R$ 50 mil a R$ 80 mil: +R$ 25,00/mês
   - Acima de R$ 80 mil: +R$ 50,00/mês

3. ALCANCE DE REBOQUE / GUINCHO 24H (OPÇÃO ÚNICA):
   - 100 km: Incluso no plano base (+R$ 0,00/mês) -> Para quem roda só na cidade;
   - 200 km: +R$ 14,90/mês -> Viagens curtas / fins de semana em cidades vizinhas;
   - 500 km: +R$ 29,90/mês (Mais popular) -> Viagens estaduais e família;
   - 1.000 km / Ilimitado: +R$ 49,90/mês -> Roda o Brasil inteiro em rodovias.

4. COBERTURAS EXTRAS E OPCIONAIS:
   - Proteção de Vidros Completa: +R$ 19,90/mês (para-brisa, vidros, faróis, lanternas, retrovisores);
   - Carro Reserva 7 dias: +R$ 18,00/mês (não acumula com 15 dias);
   - Carro Reserva 15 dias: +R$ 29,90/mês (não acumula com 7 dias);
   - Danos a Terceiros R$ 30.000: +R$ 16,90/mês (não acumula com 50k);
   - Danos a Terceiros R$ 50.000: +R$ 24,90/mês (Recomendado - não acumula com 30k);
   - Auxílio Combustível: +R$ 6,90/mês (pane seca);
   - Hospedagem Emergencial: +R$ 9,90/mês (hotel se quebrar longe de casa);
   - Pacote Motorista de App / Entregador: +R$ 29,90/mês (obrigatório se fizer Uber, 99, entregas).

COMO DEVE SER SUA CONVERSA:
- Responda sempre em português brasileiro de forma natural, calorosa e concisa (máximo 2 a 4 frases por resposta, não envie textos gigantes).
- Faça UMA pergunta por vez para não cansar o cliente.
- Descubra: 1) Nome do cliente; 2) Qual é o carro e faixa de valor aproximada; 3) Se viaja ou roda só na cidade; 4) Se usa o carro para trabalhar com app; 5) Se quer carro reserva e proteção para vidros/terceiros.
- Quando tiver as informações necessárias (ou quando o cliente pedir uma recomendação), monte o plano ideal com o valor total exato e justifique por que escolheu cada item.

IMPORTANTE - REQUISITO DE RECOMENDAÇÃO FINAL:
Sempre que você recomendar o plano definitivo para o cliente, inclua no final exato da sua mensagem a tag [PROPOSTA_PLANO] com o JSON correspondente:
[PROPOSTA_PLANO]
{
  "finalizado": true,
  "fipe_faixa": "Até R$ 50 mil",
  "fipe_adicional": 0,
  "reboque": "Reboque 200 km",
  "reboque_valor": 14.90,
  "opcionais": [
    {"id": "vidros", "title": "Proteção de Vidros Completa", "price": 19.90},
    {"id": "terceiros-50", "title": "Danos a Terceiros R$ 50.000", "price": 24.90}
  ],
  "valor_total": 159.70,
  "justificativa": "Plano ideal para quem roda na cidade com viagens no fim de semana e quer tranquilidade contra terceiros."
}
[/PROPOSTA_PLANO]
Se ainda estiver no meio da conversa fazendo perguntas, NÃO inclua essa tag ou bloco.`;

// 3. Monta o array contents de mensagens para o Gemini API
const contents = [];

for (const msg of conversationHistory) {
  if (msg.role === 'user' || msg.role === 'model') {
    contents.push({
      role: msg.role,
      parts: [{ text: msg.text || msg.content || '' }]
    });
  }
}

contents.push({
  role: 'user',
  parts: [{ text: userMessage }]
});

// 4. Monta o payload completo pronto para o Gemini
const geminiPayload = {
  system_instruction: {
    parts: [{ text: systemInstruction }]
  },
  contents: contents,
  generationConfig: {
    temperature: 0.7,
    maxOutputTokens: 1200
  }
};

return [{
  json: {
    geminiPayload,
    userMessage
  }
}];

// Extrai o texto gerado pelo Gemini e detecta bloco JSON com recomendação de plano
const item = $input.first().json;
let rawReply = '';

try {
  if (item.candidates && item.candidates[0] && item.candidates[0].content) {
    rawReply = item.candidates[0].content.parts[0].text || '';
  } else if (item.error) {
    const errMsg = item.error.message || JSON.stringify(item.error);
    rawReply = 'Desculpe, tive um problema ao conectar com a IA: ' + errMsg;
  }
} catch (e) {
  rawReply = 'Olá! Qual o seu veículo e qual uso você faz dele no dia a dia?';
}

let cleanReply = rawReply;
let plano = null;
let finalizado = false;

// 1. Tenta extrair da tag [PROPOSTA_PLANO]...[/PROPOSTA_PLANO]
const tagMatch = rawReply.match(/\[PROPOSTA_PLANO\]\s*([\s\S]*?)\s*\[\/PROPOSTA_PLANO\]/i);
if (tagMatch && tagMatch[1]) {
  try {
    plano = JSON.parse(tagMatch[1]);
    if (plano && plano.finalizado) finalizado = true;
    cleanReply = rawReply.replace(/\[PROPOSTA_PLANO\][\s\S]*?\[\/PROPOSTA_PLANO\]/gi, '').trim();
  } catch (e) {}
}

// 2. Se não achou na tag, tenta extrair de bloco de código markdown
if (!plano) {
  const jsonMatch = rawReply.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
  if (jsonMatch && jsonMatch[1]) {
    try {
      plano = JSON.parse(jsonMatch[1]);
      if (plano && plano.finalizado) finalizado = true;
      cleanReply = rawReply.replace(/```(?:json)?[\s\S]*?```/g, '').trim();
    } catch (e) {}
  }
}

// 3. Fallback: tenta detectar JSON com "finalizado": true
if (!plano) {
  const rawJsonMatch = rawReply.match(/\{[\s\S]*"finalizado"\s*:\s*true[\s\S]*\}/);
  if (rawJsonMatch) {
    try {
      plano = JSON.parse(rawJsonMatch[0]);
      if (plano && plano.finalizado) finalizado = true;
      cleanReply = rawReply.replace(rawJsonMatch[0], '').trim();
    } catch (e) {}
  }
}

return [{
  json: {
    reply: cleanReply,
    plano: plano,
    finalizado: finalizado
  }
}];
